ee:message.ee:set-payload:
%dw 2.0
output application/xml
ns soap http://schemas.xmlsoap.org/soap/envelope/
ns common http://standardbank.ao/common/types/1.0

var id = upper(error.errorType.identifier default "UNKNOWN")

// Só o código EXP-xxx é mapeado; a mensagem vem do raise-error do flow.
var codigos = {
  "CLIENTE_INVALIDO":    "EXP-001",
  "CONTA_INVALIDA":      "EXP-002",
  "CARTAO_INVALIDO":     "EXP-003",
  "REQUISICAO_INVALIDA": "EXP-400",
  "RESPOSTA_INVALIDA":   "EXP-502",
  "INVALID_NUMBER":      "EXP-400",
  "SOAP_FAULT":          "EXP-400",
  "AGENDAMENTO_INVALIDO" : "EXP-400"
}

var msg = error.description default "Não foi possível concluir a operação."
---
{
  soap#Fault: {
    faultcode:   "soap:Client",
    faultstring: msg,
    detail: {
      common#ExperienceFault: {
        common#errorCode:     codigos[id] default "EXP-400",
        common#errorMessage:  msg,
        common#timestamp:     now() as String {format: "yyyy-MM-dd'T'HH:mm:ssXXX"}
      }
    }
  }
}

%dw 2.0
output application/xml
ns soap http://schemas.xmlsoap.org/soap/envelope/
ns common http://standardbank.ao/common/types/1.0

var nsErro = upper(error.errorType.namespace default "MULE")
var idErro = upper(error.errorType.identifier default "UNKNOWN")

var e =
  if ((idErro contains "TIMEOUT") or (idErro contains "RETRY_EXHAUSTED"))
    { code: "EXP-504", msg: "O serviço demorou a responder. Tente novamente dentro de instantes." }
  else if ((idErro contains "CONNECTIVITY") or (idErro contains "CANNOT_DISPATCH")
           or (idErro contains "CANNOT_REACH") or (idErro contains "INVALID_WSDL")
           or (idErro contains "CONNECTION"))
    { code: "EXP-503", msg: "Serviço temporariamente indisponível. Tente novamente dentro de alguns minutos." }
  else if ((nsErro == "WSC") or (nsErro == "HTTP"))
    { code: "EXP-502", msg: "Não foi possível processar a operação neste momento." }
  else if ((nsErro == "APIKIT-SOAP") or (idErro contains "BAD_REQUEST"))
    { code: "EXP-400", msg: "O pedido não está no formato esperado." }
  else
    { code: "EXP-500", msg: "Ocorreu um problema. Tente novamente dentro de alguns minutos." }
---
{
  soap#Fault: {
    faultcode:   if (e.code == "EXP-400") "soap:Client" else "soap:Server",
    faultstring: e.msg,
    detail: {
      common#ExperienceFault: {
        common#errorCode:     e.code,
        common#errorMessage:  e.msg,
        common#timestamp:     now() as String {format: "yyyy-MM-dd'T'HH:mm:ssXXX"}
      }
    }
  }
}
